236	  for (let guard = 0; guard < 120; guard += 1) {
237	    const [year, monthNumber] = month.split("-").map(Number) as [number, number];
238	    const lastDay = new Date(Date.UTC(year, monthNumber, 0)).getUTCDate();
239	    const date = `${month}-${String(Math.min(day, lastDay)).padStart(2, "0")}`;
240	    if (date > end) break;
241	    if (date > start) dates.push(date);
242	    month = addMonths(month, 1);
243	  }
