/bin/bash -lc "node - <<'NODE'
const D=require('decimal.js'); D.set({precision:60}); const H=D.ROUND_HALF_UP, DOWN=D.ROUND_DOWN;
const r=(x,n,m=H)=>new D(x).toDecimalPlaces(n,m); const out=x=>r(x,8).toFixed();
const A=r(new D('1.0005166').pow(252).minus(1),8);
function dailyPct(days,decOut){const daily=r(new D(1).plus(A).pow(new D(1).div(252)).minus(1),8); const one=r(new D(1).plus(daily.times('1.04')),16,DOWN); let cum=new D(1);for(let i=0;i<days;i++)cum=r(cum.times(one),16,DOWN);return r(cum.minus(1),decOut)}
function fixed(days){return r(new D('1.1415').pow(new D(days).div(252)).minus(1),9)}
function sched(P, spec, factor){let carried=new D(0),cash=new D(0);const rows=[];for(const [pid,segments,payFirst] of spec){let acc=new D(0),paid=new D(0),pf=new D(1);for(let i=0;i<segments.length;i++){const f=factor(segments[i]);const a=r(new D(P).plus(carried).times(f),8,DOWN);acc=acc.plus(a);carried=carried.plus(a);pf=pf.times(f.plus(1));if(payFirst&&i===0){paid=paid.plus(carried);carried=new D(0)}}cash=cash.plus(paid);rows.push({pid,factor:out(pf.minus(1)),accrued:acc.toFixed(),paid:paid.toFixed(),carried:carried.toFixed()})}return {rows,total:cash.toFixed()}}
const spec14=[['Q3',[9,54],true],['Q4',[63],false],['Q1',[10,53],true],['Q2',[63],false]];
const spec15=[['Q3',[63],false],['Q4',[53,10],true],['Q1',[63],false],['Q2',[52,11],true]];
console.log('14 executor',JSON.stringify(sched('411643',spec14,n=>dailyPct(n,9)),null,2));
console.log('14 corrected source final8',JSON.stringify(sched('411643',spec14,n=>dailyPct(n,8)),null,2));
console.log('15',JSON.stringify(sched('406349',spec15,fixed),null,2));
NODE"

