  4	/**
  5	 * A procedure is the single, human-reviewable source of operational knowledge.
  6	 * A compiled skill is an immutable runtime projection of that procedure. Nobody edits the
  7	 * compiled projection directly and no runtime is allowed to invent a peer-to-peer handoff.
  8	 */
  9	
 10	export const procedureCompilerVersion = "2026.08.25-v2";
 11	
 12	/**
 13	 * The ladder a method climbs. Nothing skips a rung: `implemented` needs executable evidence,
 14	 * `ai_reviewed` needs a recorded independent review by a model that went back to the sources,
 15	 * `tested` needs the gold, adversarial and consistency runs, `ready_for_founder` is the hand-off
 16	 * to the founder's integrated evaluation, and `production` needs the founder's approval.
 17	 */
 18	export const procedureMaturitySchema = z.enum(["draft", "candidate", "implemented", "ai_reviewed", "tested", "ready_for_founder", "production"]);
 19	export const procedureMaturityOrder: readonly ProcedureMaturity[] = ["draft", "candidate", "implemented", "ai_reviewed", "tested", "ready_for_founder", "production"];
 20	export const maturityRank = (maturity: ProcedureMaturity): number => procedureMaturityOrder.indexOf(maturity);
 21	export type ProcedureMaturity = z.infer<typeof procedureMaturitySchema>;
 22	
 23	export const procedureRoleSchema = z.enum([
 24	  "intake_evidence",
 25	  "financial_analysis",
 26	  "credit_structuring",
 27	  "institutional_materials",
 28	  "market_distribution",
 29	  "independent_quality_control",
 30	]);
 31	export type ProcedureRole = z.infer<typeof procedureRoleSchema>;
 32	
 33	export const procedureStageSchema = z.number().int().min(1).max(12);
 34	export type ProcedureStage = z.infer<typeof procedureStageSchema>;
 35	
 36	export const procedureAuthoritySchema = z.enum(["LEI", "DEF", "CASA", "MERCADO", "HEURÍSTICA"]);
 37	export type ProcedureAuthority = z.infer<typeof procedureAuthoritySchema>;
 38	
 39	const bilingualSchema = z.object({pt: z.string().trim().min(1), en: z.string().trim().min(1)}).strict();
 40	
 41	export const outputValueTypeSchema = z.enum([
 42	  "string",
 43	  "number",
 44	  "decimal_string",
 45	  "boolean",
 46	  "date",
 47	  "enum",
 48	  "object",
 49	  "array",
 50	]);
 51	
 52	export const procedureOutputFieldSchema = z.object({
 53	  id: z.string().regex(/^[a-z][a-z0-9_.-]*$/),
 54	  type: outputValueTypeSchema,
 55	  required: z.boolean(),
 56	  description: z.string().trim().min(1),
 57	  /** Material assertions must point to evidence or a traced calculation. */
 58	  evidenceRequired: z.boolean().default(true),
 59	  allowedValues: z.array(z.string().min(1)).min(1).optional(),
 60	}).strict();
